    "wa.nameTitle": { en: "Your full name", es: "Tu nombre completo" },
    "wa.nameHint": { en: "Optional. Type it as your bank prints it. It helps the app tell your own transfers apart from payments to other people. You can add or change it later in More → My profile.", es: "Opcional. Escríbelo como lo escribe tu banco. Ayuda a la app a distinguir tus propias transferencias de los pagos a otras personas. Puedes agregarlo o cambiarlo después en Más → Mi perfil." },
    "wa.namePlaceholder": { en: "First and last names", es: "Nombres y apellidos" },
    "review.maybeYours": { en: "Maybe yours? If this went to your own account, tap “Make it a transfer”.", es: "¿Será tuya? Si fue a tu propia cuenta, toca “Pasar a transferencia”." },
    "ownerNames.addLabel": { en: "Add a name as it appears on your accounts", es: "Agrega un nombre como aparece en tus cuentas" },
