    "mainCur.title": { en: "Main currency", es: "Moneda principal" },
    "mainCur.current": { en: "Your main currency: ★ {code}", es: "Tu moneda principal: ★ {code}" },
    "mainCur.reversible": { en: "You can change this at any time, and switching back restores exactly what you had. Nothing in your data is rewritten: your entries keep their own currencies, and only the totals are shown in the main currency.", es: "Puedes cambiarla cuando quieras, y volver atrás deja todo exactamente como estaba. No se reescribe nada de tus datos: tus movimientos conservan su propia moneda y solo los totales se muestran en la moneda principal." },
    "mainCur.change": { en: "Change main currency…", es: "Cambiar moneda principal…" },
    "mainCur.confirm": { en: "Switch your main currency from {from} to {to}? Totals, budgets and reports will be shown in {to}. You can switch back at any time.", es: "¿Cambiar tu moneda principal de {from} a {to}? Los totales, presupuestos y reportes se mostrarán en {to}. Puedes volver atrás cuando quieras." },
    "mainCur.rateQuestion": { en: "How many {to} is 1 {from} worth today?", es: "¿Cuántos {to} vale hoy 1 {from}?" },
    "mainCur.estimate": { en: "Months before {month} use that first {to} rate as an estimate. You can refine them under More → Currencies, and everything updates by itself.", es: "Los meses anteriores a {month} usan ese primer tipo de cambio de {to} como estimado. Puedes afinarlos en Más → Monedas y todo se actualiza solo." },
