    "wa.currency": { en: "Currency", es: "Moneda" },
    "wa.type.debit": { en: "Savings or debit account", es: "Cuenta de ahorros o débito" },
    "wa.type.sueldo": { en: "Salary account (where your salary arrives)", es: "Cuenta sueldo (donde recibes tu sueldo)" },
    "wa.type.credit": { en: "Credit card", es: "Tarjeta de crédito" },
    "wa.alias": { en: "Name (optional)", es: "Nombre (opcional)" },
    "wa.aliasHint": { en: "If you leave it empty, the app names the account for you.", es: "Si lo dejas vacío, la app le pone un nombre." },
    "wa.last4": { en: "Last 4 digits (optional)", es: "Últimos 4 dígitos (opcional)" },
    "wa.last4Hint": { en: "They help the app recognize your bank emails. Never the full number.", es: "Ayudan a la app a reconocer los correos de tu banco. Nunca el número completo." },
    "wa.showLast4": { en: "Show the last 4 digits in the name", es: "Mostrar los últimos 4 dígitos en el nombre" },
