    "be.need.check.sub": { en: "Your bank has an email for these, but none has reached the app yet. Turn the alert on in your bank's app (see By bank) and they will arrive by themselves.", es: "Tu banco tiene un correo para estos, pero todavía no ha llegado ninguno a la app. Activa la alerta en la app de tu banco (mira Por banco) y llegarán solos." },
    "be.need.optional": { en: "Optional: these arrive by email", es: "Opcional: estos llegan por correo" },
    "be.need.optional.sub": { en: "Emails from this bank are reaching the app, so these probably did not need to be added by hand. Next time, wait for the email and confirm it in Needs review.", es: "Los correos de este banco sí llegan a la app, así que probablemente no hacía falta agregar estos a mano. La próxima vez, espera el correo y confírmalo en Por revisar." },
