    "more.erase": { en: "🗑️ Delete everything", es: "🗑️ Borrar todo" },
    "erase.title": { en: "Delete everything", es: "Borrar todo" },
    "erase.intro": { en: "This removes the app from your Google account for good. All of this will be deleted:", es: "Esto quita la app de tu cuenta de Google para siempre. Se borrará todo esto:" },
    "erase.item1": { en: "Your Google Sheet “Expense Tracker”, with all your expenses, accounts, budgets and loans.", es: "Tu archivo de Google Sheets “Expense Tracker”, con todos tus gastos, cuentas, presupuestos y préstamos." },
    "erase.item2": { en: "Your app and its timers.", es: "Tu app y sus temporizadores." },
    "erase.item3": { en: "The permissions your app and the setup page have in your Google account (the setup page removes them).", es: "Los permisos que tu app y la página de configuración tienen en tu cuenta de Google (los quita la página de configuración)." },
    "erase.item4": { en: "You will be signed out on all your devices.", es: "Se cerrará la sesión en todos tus dispositivos." },
    "erase.noUndo": { en: "This cannot be undone. If you want to keep a copy of your data, close this and use More → My data → Export my data first.", es: "Esto no se puede deshacer. Si quieres guardar una copia de tus datos, cierra esto y usa antes Más → Mis datos → Exportar mis datos." },
    "erase.typePrompt": { en: "To confirm, type DELETE here:", es: "Para confirmar, escribe BORRAR aquí:" },
    "erase.word": { en: "DELETE", es: "BORRAR" },
    "erase.btn": { en: "Delete everything", es: "Borrar todo" },
    "erase.working": { en: "Deleting…", es: "Borrando…" },
    "erase.failed": { en: "Something went wrong, so nothing was changed. Check your connection and try again.", es: "Algo salió mal, así que no se cambió nada. Revisa tu conexión e inténtalo de nuevo." },
    "erase.step2Title": { en: "Last step: finish in Google", es: "Último paso: terminar en Google" },
    "erase.step2Body": { en: "Your data is erased, your app is signed out everywhere and it gave back its permission. One step is left: the setup page, signed in to your Google account, deletes the Google Sheet and the app itself and removes its own permission. It takes about a minute.", es: "Tus datos están borrados, tu app cerró la sesión en todos lados y devolvió su permiso. Falta un paso: la página de configuración, con tu cuenta de Google, elimina el archivo de Google Sheets y la app misma, y quita su propio permiso. Toma cerca de un minuto." },
    "erase.finishBtn": { en: "Finish deleting in Google", es: "Terminar de borrar en Google" },
    "erase.copy": { en: "Copy the link", es: "Copiar el enlace" },
    "erase.hintHome": { en: "Google's sign-in works best in Safari. Tap “Open in Safari” and follow the steps. If Safari does not open, tap “Copy the link”, open Safari and paste it in the address bar.", es: "El inicio de sesión de Google funciona mejor en Safari. Toca “Abrir en Safari” y sigue los pasos. Si Safari no se abre, toca “Copiar el enlace”, abre Safari y pégalo en la barra de direcciones." },
    "erase.hintSafari": { en: "Tap “Finish deleting in Google” and follow the steps.", es: "Toca “Terminar de borrar en Google” y sigue los pasos." },
    "erase.later": { en: "Not now", es: "Ahora no" },
    "erase.signedOut": { en: "Your data was erased. To finish removing the app, open the setup page again from Safari and add #remove to its address.", es: "Tus datos se borraron. Para terminar de quitar la app, abre otra vez la página de configuración en Safari y agrega #remove al final de su dirección." },

