    "categories.hideHint": { en: "Hide keeps past entries intact but removes the category from every list you pick from. Delete removes it for good; if entries use it, you choose where they move.", es: "Ocultar conserva los movimientos anteriores pero quita la categoría de todas las listas donde eliges. Eliminar la borra para siempre; si hay movimientos que la usan, eliges a dónde pasan." },
    "categories.hide": { en: "Hide", es: "Ocultar" },
