    "notauto.tipNoBot.yape_in": { en: "Banks may send no email for money you receive. If none arrives, add it by hand.", es: "Puede que los bancos no envíen correo por el dinero que recibes. Si no llega, agrégalo a mano." },
    "notauto.tipNoBot.yape_out": { en: "If the bank's email did not arrive, add it by hand.", es: "Si no llegó el correo del banco, agrégalo a mano." },
