    "hist.aside.title": { en: "Lines set aside ({n})", es: "Líneas dejadas aparte ({n})" },
    "hist.aside.hint": { en: "Tap one if it is really spending, income, a transfer or an investment and you want it in your history. A transfer is recorded on this account only; when the other account's statement arrives, it completes it.", es: "Toca una si en realidad es un gasto, un ingreso, una transferencia o una inversión y la quieres en tu historial. Una transferencia se registra solo en esta cuenta; cuando llegue el estado de cuenta de la otra, la completa." },
    "hist.people.title": { en: "Payments with people ({n})", es: "Pagos con personas ({n})" },
