    "hist.income.title": { en: "Income lines ({n})", es: "Líneas de ingreso ({n})" },
    "hist.income.hint": { en: "Counted as income by default. If one is really something else, change it here: a transfer from your own account, money back from an investment, or a loan or repayment (finished in Needs review).", es: "Se cuentan como ingreso por defecto. Si alguna en realidad es otra cosa, cámbiala aquí: una transferencia desde tu propia cuenta, dinero que vuelve de una inversión, o un préstamo o repago (se termina en Por revisar)." },
