    "hist.confirm": { en: { one: "{n} entry will be added to your history, confirmed.", other: "{n} entries will be added to your history, confirmed. Any without a category wait in Tidy my history." }, es: { one: "Se agregará {n} movimiento a tu historial, confirmado.", other: "Se agregarán {n} movimientos a tu historial, confirmados. Los que no tengan categoría esperarán en Ordenar mi historial." } },
    "hist.saving": { en: "Adding to your history… with many statements this can take up to a minute. Keep this screen open.", es: "Agregando a tu historial… con muchos estados de cuenta puede tardar hasta un minuto. Deja esta pantalla abierta." },
